mapper.select:
select ppio.id id, ppio.org_id orgid, ppio.patient_id patientId, ppio.prepayment_number prepaymentNumber, ppio.crt_time crtTime, ppio.type, pbio.name name, CAST(IFNULL((ppio.prepayment_principal+ppio.prepayment_bonus),0) AS decimal(15,2)) prepaymentMoneySum, CAST(IFNULL(ppio.prepayment_bonus,0) AS decimal(15,2)) prepaymentBonus, CAST(IFNULL(ppio.prepayment_principal,0) AS decimal(15,2)) prepaymentPrincipal from patient_prepayments_info ppio join patient_base_info pbio on ppio.patient_id = pbio.id
ppio.patient_id = #{patientId}
AND ppio.type IN
#{item}

select

from patient_prepayments_info ppio
where ppio.prepayment_number = #{prepaidId}

select

from patient_prepayments_info ppio
where ppio.patient_id = #{patientId}
and ppio.type = #{type}

select
    IF(prepayment_number is null,'000000',substr( MAX(prepayment_number), -6, 6 )) as maxnum
from patient_prepayments_info
where
left(prepayment_number,1) = #{prefix}
and org_id = #{orgId}
